action.mutation:
mutation Mutation($supplierAddressPayload: [SupplierAddressCreatePayloadInput!]!, 
  	$facilityPayload: [FacilityCreatePayloadInput!]!,
		$workcenterPayload: [WorkcenterCreatePayloadInput!]!) {
  createSupplierAddress(payload: $supplierAddressPayload) {
    id	
  }

  createFacility(payload: $facilityPayload) {
    id	
  }

  createWorkcenter(payload: $workcenterPayload) {
    id	
  }
}

transforms.pre:
(
$isOutsideProcessor := rowData.supplierType.id = "Outside Processor";
$supplierId := $$.rowData.id;
$facilityId := $cuid();
$supplierAddressId := $cuid();


{
    "supplierAddressPayload": {
    "create": $merge([data, {
        "id": $supplierAddressId,
        "supplierId": $supplierId,
        "code":$$.rowdata.code,
        "main": data.main,
        "plantIdentifier": data.plantIdentifier,
        "address": data.address,
        "active": data.active
        }])
    },
    "facilityPayload": $isOutsideProcessor ? {
      "create": {
        "id": $facilityId,
        "supplierAddressId": $supplierAddressId,
        "code": data.code,
        "name": data.code,
        "typeId": "Outside"
      }
    }: [],
    "workcenterPayload": $isOutsideProcessor ? {
      "create":{
        "name": data.code,
        "code": data.code,
        "supplierId": $supplierId,
        "concurrency": 999999,
        "workcenterTypeId": "Outside Processor",
        "shiftGroupId": "Default",
        "modeGroupId": "Default",
        "facilityId":$facilityId
      }
    } : []
}

)

action.mutation:
mutation UpdateSupplier($payload: [SupplierUpdatePayloadInput!]!) {
  mutation: updateSupplier(payload: $payload) { 
    id
    code
  }
}

action.query:
query Query($where: SupplierWhereInput){
  supplier (where: $where){
    edges {
      node {
        id
        active
        supplierAddresses {
          edges {
            node {
              id
              code
              active
              facility {
                name
                id
                active
              }
            }
          }
        }
      }
    }
  }
}

